11	// Author: Tang, Yao
12	// Description:
13	
14	`timescale 1ns/1ns
15	`include "define.v"
16	
17	module cu_handler (
18	  input                                 clk                          ,
19	  input                                 rst_n                        ,
20	
21	  input                                 wg_alloc_en_i                ,
22	  input   [`WG_ID_WIDTH-1:0]            wg_alloc_wg_id_i             ,
23	  input   [`WF_COUNT_WIDTH_PER_WG-1:0]  wg_alloc_wf_count_i          ,
24	  input                                 ready_for_dispatch2cu_i      ,
25	  input                                 cu2dispatch_wf_done_i        ,
26	  input   [`TAG_WIDTH-1:0]              cu2dispatch_wf_tag_done_i    ,
27	  input                                 wg_done_ack_i                ,
28	
29	  output                                dispatch2cu_wf_dispatch_o    ,
30	  output  [`TAG_WIDTH-1:0]              dispatch2cu_wf_tag_dispatch_o,
31	  output                                wg_done_valid_o              ,
32	  output  [`WG_ID_WIDTH-1:0]            wg_done_wg_id_o              ,
33	  output                                invalid_due_to_not_ready_o      
34	  );
35	
36	  localparam  TAG_WF_COUNT_L       = 0                                               ;
37	  localparam  TAG_WF_COUNT_H       = TAG_WF_COUNT_L + `WF_COUNT_WIDTH_PER_WG - 1     ;
38	  localparam  TAG_WG_SLOT_ID_L     = TAG_WF_COUNT_H + 1                              ;
39	  localparam  TAG_WG_SLOT_ID_H     = TAG_WG_SLOT_ID_L + `WG_SLOT_ID_WIDTH - 1        ;
40	
41	  localparam  INFO_RAM_WORD_WIDTH  = `WG_ID_WIDTH + `WF_COUNT_WIDTH_PER_WG           ;
42	  localparam  INFO_RAM_WG_COUNT_L  = 0                                               ;
43	  localparam  INFO_RAM_WG_COUNT_H  = INFO_RAM_WG_COUNT_L + `WF_COUNT_WIDTH_PER_WG - 1;
44	  localparam  INFO_RAM_WG_ID_L     = INFO_RAM_WG_COUNT_H + 1                         ;
45	  localparam  INFO_RAM_WG_ID_H     = INFO_RAM_WG_ID_L + `WG_ID_WIDTH - 1             ;
46	
47	  localparam  ST_ALLOC_IDLE        = 2'b01                                           ;
48	  localparam  ST_ALLOCATING        = 2'b10                                           ;
49	
50	  localparam  ST_DEALLOC_IDLE      = 3'b001                                          ;
51	  localparam  ST_DEALLOC_READ_RAM  = 3'b010                                          ;
52	  localparam  ST_DEALLOC_PROPAGATE = 3'b100                                          ;
53	
54	  // On alloc:
55	  // Get first wf free slot, slot of first wf is slot of cu
56	  // zero counter, store wf_id and wf_count
57	  // output tag of each cu
58	  reg   [`WG_SLOT_ID_WIDTH-1:0]                       next_free_slot                 ;
59	  wire  [`WG_SLOT_ID_WIDTH-1:0]                       next_free_slot_comb            ;
60	  reg   [`NUMBER_WF_SLOTS-1:0]                        used_slot_bitmap               ;
61	  reg   [`NUMBER_WF_SLOTS-1:0]                        pending_wg_bitmap              ;
62	  reg   [`NUMBER_WF_SLOTS*`WF_COUNT_WIDTH_PER_WG-1:0] pending_wf_count               ;
63	  reg   [`WF_COUNT_WIDTH_PER_WG-1:0]                  curr_alloc_wf_count            ;
64	  reg   [`WG_SLOT_ID_WIDTH-1:0]                       curr_alloc_wf_slot             ;
65	  reg                                                 dispatch2cu_wf_dispatch_reg    ;
66	  reg   [`TAG_WIDTH-1:0]                              dispatch2cu_wf_tag_dispatch_reg;
67	
68	  // On dealloc:
69	  // Look up counter
70	  // Check if wg finished
71	  // Notify gpu_interface
72	  reg                                   next_served_dealloc_valid     ;
73	  wire                                  next_served_dealloc_valid_comb;
74	  reg   [`WG_SLOT_ID_WIDTH-1:0]         next_served_dealloc           ;
75	  wire  [`WG_SLOT_ID_WIDTH-1:0]         next_served_dealloc_comb      ;
76	
77	  reg   [`WG_SLOT_ID_WIDTH-1:0]         curr_dealloc_wg_slot          ;
78	  //reg   [`WF_COUNT_WIDTH_PER_WG-1:0]    curr_dealloc_wf_counter       ;
79	  //reg   [`WG_ID_WIDTH-1:0]              curr_dealloc_wf_id            ;
80	  reg                                   info_ram_rd_en                ;
81	  reg                                   info_ram_rd_valid             ;
82	  wire  [INFO_RAM_WORD_WIDTH-1:0]       info_ram_rd_reg               ;
83	  reg                                   info_ram_wr_en                ;
84	  reg   [`WG_SLOT_ID_WIDTH-1:0]         info_ram_wr_addr              ;
85	  reg   [INFO_RAM_WORD_WIDTH-1:0]       info_ram_wr_reg               ;
86	  reg                                   wg_done_valid_reg             ;
87	  reg   [`WG_ID_WIDTH-1:0]              wg_done_wg_id_reg             ;
88	  reg   [`WF_COUNT_WIDTH_PER_WG-1:0]    curr_wf_count                 ;
89	  reg                                   invalid_due_to_not_ready_reg  ;
90	  wire  [`WG_SLOT_ID_WIDTH-1:0]         cu2dispatch_wf_tag_done_slot  ;
91	
92	  reg   [1:0]                           alloc_st                      ;
93	  reg   [2:0]                           dealloc_st                    ;
94	
95	  wire                                  found_free_slot_valid2        ;
96	  wire  [`WG_SLOT_ID_WIDTH-1:0]         found_free_slot_id2           ;
97	  wire                                  found_free_slot_valid         ;
98	  wire  [`WG_SLOT_ID_WIDTH-1:0]         found_free_slot_id            ;
99	  wire  [`NUMBER_WF_SLOTS-1:0]          grant                         ;
100	  wire  [`NUMBER_WF_SLOTS-1:0]          grant2                        ;
101	  reg                                   next_free_slot_valid          ;
102	
103	  always@(posedge clk or negedge rst_n) begin
104	    if(!rst_n) begin
105	      next_free_slot            <= 'd0;
106	      next_free_slot_valid      <= 'd0;
107	      next_served_dealloc_valid <= 'd0;
108	      next_served_dealloc       <= 'd0;
109	      info_ram_rd_valid         <= 'd0;
110	    end
111	    else begin
112	      next_free_slot            <= next_free_slot_comb           ;
113	      next_free_slot_valid      <= found_free_slot_valid2        ;
114	      next_served_dealloc_valid <= next_served_dealloc_valid_comb;
115	      next_served_dealloc       <= next_served_dealloc_comb      ;
116	      info_ram_rd_valid         <= info_ram_rd_en                ;
117	    end
118	  end
119	
120	  ram #(
121	    .WORD_SIZE(INFO_RAM_WORD_WIDTH),
122	    .ADDR_SIZE(`WG_SLOT_ID_WIDTH  ),
123	    .NUM_WORDS(`NUMBER_WF_SLOTS   )
124	  )
125	  info_ram (
126	    .clk      (clk                 ), 
127	    .rst_n    (rst_n               ),     
128	             
129	    .rd_addr_i(curr_dealloc_wg_slot),
130	    .wr_addr_i(info_ram_wr_addr    ), 
131	    .wr_word_i(info_ram_wr_reg     ), 
132	    .wr_en_i  (info_ram_wr_en      ), 
133	    .rd_en_i  (info_ram_rd_en      ),   
134	             
135	    .rd_word_o(info_ram_rd_reg     )
136	    );
137	
138	  //alloc state machine
139	  always@(posedge clk or negedge rst_n) begin
140	    if(!rst_n) begin
141	      alloc_st <= ST_ALLOC_IDLE;
142	    end
143	    else begin
144	      case(alloc_st)
145	        ST_ALLOC_IDLE : alloc_st <= (wg_alloc_en_i && next_free_slot_valid) ? ST_ALLOCATING : ST_ALLOC_IDLE;
146	        ST_ALLOCATING : alloc_st <= (curr_alloc_wf_count != 0) ? ST_ALLOCATING : ST_ALLOC_IDLE             ;
147	        default       : alloc_st <= ST_ALLOC_IDLE                                                          ;
148	      endcase
149	    end
150	  end
151	
152	  //dealloc state machine
153	  always@(posedge clk or negedge rst_n) begin
154	    if(!rst_n) begin
155	      dealloc_st <= ST_DEALLOC_IDLE;
156	    end
157	    else begin
158	      case(dealloc_st)
159	        ST_DEALLOC_IDLE      : dealloc_st <= next_served_dealloc_valid ? ST_DEALLOC_READ_RAM : ST_DEALLOC_IDLE                                        ;
160	        ST_DEALLOC_READ_RAM  : dealloc_st <= info_ram_rd_valid ? ((curr_wf_count == 0) ? ST_DEALLOC_PROPAGATE : ST_DEALLOC_IDLE) : ST_DEALLOC_READ_RAM;
161	        ST_DEALLOC_PROPAGATE : dealloc_st <= wg_done_ack_i ? ST_DEALLOC_IDLE : ST_DEALLOC_PROPAGATE                                                   ;
162	        default              : dealloc_st <= ST_DEALLOC_IDLE                                                                                          ;  
163	      endcase
164	    end
165	  end
166	
167	  always@(posedge clk or negedge rst_n) begin
168	    if(!rst_n) begin
169	      info_ram_wr_en                  <= 'd0;
170	      info_ram_wr_addr                <= 'd0;
171	      info_ram_wr_reg                 <= 'd0;
172	      info_ram_rd_en                  <= 'd0;
173	      curr_alloc_wf_count             <= 'd0;
174	      curr_alloc_wf_slot              <= 'd0;
175	      curr_dealloc_wg_slot            <= 'd0;
176	      curr_wf_count                   <= 'd0;
177	      used_slot_bitmap                <= 'd0;
178	      dispatch2cu_wf_dispatch_reg     <= 'd0;
179	      dispatch2cu_wf_tag_dispatch_reg <= 'd0;
180	      invalid_due_to_not_ready_reg    <= 'd0;
181	      wg_done_valid_reg               <= 'd0;
182	      wg_done_wg_id_reg               <= 'd0;
183	    end
184	
185	    else if(alloc_st == ST_ALLOC_IDLE && dealloc_st == ST_DEALLOC_IDLE) begin
186	      if(wg_alloc_en_i && next_free_slot_valid) begin
187	        info_ram_wr_en                                                                        <= 1'b1                                  ;
188	        info_ram_rd_en                                                                        <= 1'b0                                  ;
189	        dispatch2cu_wf_dispatch_reg                                                           <= 1'b0                                  ; 
190	        invalid_due_to_not_ready_reg                                                          <= 1'b0                                  ;   
191	        wg_done_valid_reg                                                                     <= 1'b0                                  ;
192	        info_ram_wr_addr                                                                      <= next_free_slot                        ;
193	        info_ram_wr_reg                                                                       <= {wg_alloc_wg_id_i,wg_alloc_wf_count_i};
194	        curr_alloc_wf_count                                                                   <= wg_alloc_wf_count_i                   ;
195	        curr_alloc_wf_slot                                                                    <= next_free_slot                        ;
196	        used_slot_bitmap[next_free_slot]                                                      <= 1'b1                                  ;
197	        //pending_wf_count[(next_free_slot+1)*`WF_COUNT_WIDTH_PER_WG-1-:`WF_COUNT_WIDTH_PER_WG] <= wg_alloc_wf_count_i                   ;
198	      end
199	      else if(next_served_dealloc_valid) begin
200	        info_ram_wr_en                         <= 1'b0                                                                                      ;
201	        info_ram_rd_en                         <= 1'b1                                                                                      ;
202	        dispatch2cu_wf_dispatch_reg            <= 1'b0                                                                                      ; 
203	        invalid_due_to_not_ready_reg           <= 1'b0                                                                                      ;   
204	        wg_done_valid_reg                      <= 1'b0                                                                                      ;
205	        curr_dealloc_wg_slot                   <= next_served_dealloc                                                                       ;
206	        curr_wf_count                          <= pending_wf_count[(next_served_dealloc+1)*`WF_COUNT_WIDTH_PER_WG-1-:`WF_COUNT_WIDTH_PER_WG];
207	        //pending_wg_bitmap[next_served_dealloc] <= 1'b0                                                                                      ;
208	      end
209	      else begin
210	        info_ram_wr_en               <= 1'b0;
211	        info_ram_rd_en               <= 1'b0;
212	        dispatch2cu_wf_dispatch_reg  <= 1'b0; 
213	        invalid_due_to_not_ready_reg <= 1'b0;   
214	        wg_done_valid_reg            <= 1'b0;
215	      end
216	    end
217	
218	    else if(alloc_st == ST_ALLOCATING && dealloc_st == ST_DEALLOC_IDLE) begin
219	      if(curr_alloc_wf_count != 0) begin
220	        if(ready_for_dispatch2cu_i) begin// Send the counter just to make sure the cu does not have two wf with the same tag
221	          info_ram_wr_en                  <= 1'b0                                        ;
222	          info_ram_rd_en                  <= 1'b0                                        ;
223	          dispatch2cu_wf_dispatch_reg     <= 1'b1                                        ; 
224	          invalid_due_to_not_ready_reg    <= 1'b0                                        ;   
225	          wg_done_valid_reg               <= 1'b0                                        ;
226	          dispatch2cu_wf_tag_dispatch_reg <= {curr_alloc_wf_slot,(curr_alloc_wf_count-1)};
227	          curr_alloc_wf_count             <= curr_alloc_wf_count - 1                     ;
228	        end
229	        else begin
230	          info_ram_wr_en               <= 1'b0;
231	          info_ram_rd_en               <= 1'b0;
232	          dispatch2cu_wf_dispatch_reg  <= 1'b0; 
233	          invalid_due_to_not_ready_reg <= 1'b1;   
234	          wg_done_valid_reg            <= 1'b0;
235	        end
236	      end
237	      else begin
238	        info_ram_wr_en               <= 1'b0;
239	        info_ram_rd_en               <= 1'b0;
240	        dispatch2cu_wf_dispatch_reg  <= 1'b0; 
241	        invalid_due_to_not_ready_reg <= 1'b0;   
242	        wg_done_valid_reg            <= 1'b0;
243	      end
244	    end
245	
246	    else if(alloc_st == ST_ALLOC_IDLE && dealloc_st == ST_DEALLOC_READ_RAM) begin
247	      if(info_ram_rd_valid) begin
248	        if(curr_wf_count == 0) begin
249	          info_ram_wr_en                         <= 1'b0                                              ;
250	          info_ram_rd_en                         <= 1'b0                                              ;
251	          dispatch2cu_wf_dispatch_reg            <= 1'b0                                              ; 
252	          invalid_due_to_not_ready_reg           <= 1'b0                                              ;   
253	          wg_done_valid_reg                      <= 1'b1                                              ;
254	          wg_done_wg_id_reg                      <= info_ram_rd_reg[INFO_RAM_WG_ID_H:INFO_RAM_WG_ID_L];
255	          used_slot_bitmap[curr_dealloc_wg_slot] <= 1'b0                                              ;
256	        end
257	        else begin
258	          info_ram_wr_en               <= 1'b0;
259	          info_ram_rd_en               <= 1'b0;
260	          dispatch2cu_wf_dispatch_reg  <= 1'b0; 
261	          invalid_due_to_not_ready_reg <= 1'b0;   
262	          wg_done_valid_reg            <= 1'b0;
263	        end
264	      end
265	      else begin
266	        info_ram_wr_en               <= 1'b0;
267	        info_ram_rd_en               <= 1'b0;
268	        dispatch2cu_wf_dispatch_reg  <= 1'b0; 
269	        invalid_due_to_not_ready_reg <= 1'b0;   
270	        wg_done_valid_reg            <= 1'b0;
271	      end
272	    end
273	
274	    else if(alloc_st == ST_ALLOC_IDLE && dealloc_st == ST_DEALLOC_PROPAGATE) begin
275	      if(wg_done_ack_i) begin
276	        info_ram_wr_en               <= 1'b0;
277	        info_ram_rd_en               <= 1'b0;
278	        dispatch2cu_wf_dispatch_reg  <= 1'b0; 
279	        invalid_due_to_not_ready_reg <= 1'b0;   
280	        wg_done_valid_reg            <= 1'b0;
281	      end
282	      else begin
283	        info_ram_wr_en               <= 1'b0;
284	        info_ram_rd_en               <= 1'b0;
285	        dispatch2cu_wf_dispatch_reg  <= 1'b0; 
286	        invalid_due_to_not_ready_reg <= 1'b0;   
287	        wg_done_valid_reg            <= 1'b1;
288	      end
289	    end
290	
291	    else begin
292	      info_ram_wr_en               <= 1'b0;
293	      info_ram_rd_en               <= 1'b0;
294	      dispatch2cu_wf_dispatch_reg  <= 1'b0; 
295	      invalid_due_to_not_ready_reg <= 1'b0;   
296	      wg_done_valid_reg            <= 1'b0;
297	    end
298	  end
299	
300	  assign cu2dispatch_wf_tag_done_slot = cu2dispatch_wf_tag_done_i[TAG_WG_SLOT_ID_H:TAG_WG_SLOT_ID_L];
301	  always@(posedge clk or negedge rst_n) begin
302	    if(!rst_n) begin
303	      pending_wg_bitmap <= 'd0;
304	      pending_wf_count  <= 'd0;
305	    end
306	    else if(cu2dispatch_wf_done_i) begin
307	      pending_wg_bitmap[cu2dispatch_wf_tag_done_slot]                                                     <= 1'b1                                                                                                   ;
308	      pending_wf_count[(cu2dispatch_wf_tag_done_slot+1)*`WF_COUNT_WIDTH_PER_WG-1-:`WF_COUNT_WIDTH_PER_WG] <= pending_wf_count[(cu2dispatch_wf_tag_done_slot+1)*`WF_COUNT_WIDTH_PER_WG-1-:`WF_COUNT_WIDTH_PER_WG] - 1;
309	    end
310	    else if(alloc_st == ST_ALLOC_IDLE && dealloc_st == ST_DEALLOC_IDLE) begin
311	      if(wg_alloc_en_i && next_free_slot_valid) begin
312	        pending_wf_count[(next_free_slot+1)*`WF_COUNT_WIDTH_PER_WG-1-:`WF_COUNT_WIDTH_PER_WG] <= wg_alloc_wf_count_i;
313	      end
314	      else if(next_served_dealloc_valid) begin
315	        pending_wg_bitmap[next_served_dealloc] <= 1'b0;
316	      end
317	      else begin
318	        pending_wg_bitmap <= pending_wg_bitmap;
319	        pending_wf_count  <= pending_wf_count ;
320	      end
321	    end 
322	    else begin
323	      pending_wg_bitmap <= pending_wg_bitmap;
324	      pending_wf_count  <= pending_wf_count ;
325	    end
326	  end
327	
328	  assign dispatch2cu_wf_dispatch_o     = dispatch2cu_wf_dispatch_reg    ;
329	  assign dispatch2cu_wf_tag_dispatch_o = dispatch2cu_wf_tag_dispatch_reg;
330	
331	  assign wg_done_valid_o = wg_done_valid_reg;
332	  assign wg_done_wg_id_o = wg_done_wg_id_reg;
333	
334	  //finds the next served deallocation
335	  assign found_free_slot_valid          = |pending_wg_bitmap   ;
336	  assign next_served_dealloc_valid_comb = found_free_slot_valid;
337	  assign next_served_dealloc_comb       = found_free_slot_id   ;
338	
339	  fixed_pri_arb #(
340	    .ARB_WIDTH(`NUMBER_WF_SLOTS)
341	  )
342	  U_fixed_pri_arb (
343	    .req  (pending_wg_bitmap),
344	    .grant(grant            )
345	    );
346	
347	  one2bin #(
348	    .ONE_WIDTH(`NUMBER_WF_SLOTS ),
349	    .BIN_WIDTH(`WG_SLOT_ID_WIDTH)
350	  )
351	  U_one2bin (
352	    .oh (grant             ),
353	    .bin(found_free_slot_id)
354	    );
355	
356	  //finds next free slot
357	  assign found_free_slot_valid2 = |(~used_slot_bitmap);
358	  assign next_free_slot_comb    = found_free_slot_id2 ;
359	
360	  fixed_pri_arb #(
361	    .ARB_WIDTH(`NUMBER_WF_SLOTS)
362	  )
363	  U_fixed_pri_arb2 (
364	    .req  (~used_slot_bitmap),
365	    .grant(grant2           )
366	    );
367	
368	  one2bin #(
369	    .ONE_WIDTH(`NUMBER_WF_SLOTS ),
370	    .BIN_WIDTH(`WG_SLOT_ID_WIDTH)
371	  )
372	  U_one2bin2 (
373	    .oh (grant2             ),
374	    .bin(found_free_slot_id2)
375	    );
376	
377	  assign invalid_due_to_not_ready_o = invalid_due_to_not_ready_reg;
378	
379	endmodule
380	
