91	  localparam  KNL_SZ_3D_L    = START_PC_H + 1                        ;
92	  localparam  KNL_SZ_3D_H    = KNL_SZ_3D_L + 3 * `WG_SIZE_X_WIDTH - 1;
93	  localparam  PDS_BASEADDR_L = KNL_SZ_3D_H + 1                       ;
94	  localparam  PDS_BASEADDR_H = PDS_BASEADDR_L + `MEM_ADDR_WIDTH - 1  ;
95	  localparam  CSR_KNL_L      = PDS_BASEADDR_H + 1                    ;
