540	          inflight_wg_buffer_csr_knl_reg              <= ready_tbl_rd_reg[CSR_KNL_H:CSR_KNL_L]          ;
541	          inflight_wg_buffer_gds_baseaddr_reg         <= ready_tbl_rd_reg[GDS_BASEADDR_H:GDS_BASEADDR_L];
542	          inflight_tbl_alloc_st                       <= ST_ALLOC_GET_ALLOC_WG                          ;
543	        end
544	
545	        ST_ALLOC_FIND_REJECTED : begin//find the rejected wg
546	          if(tbl_walk_rd_valid) begin
547	            if((table_walk_rd_reg[WG_ID_H:WG_ID_L] == tbl_walk_wg_id_searched) && waiting_tbl_pending[tbl_walk_idx]) begin
548	              inflight_tbl_alloc_st            <= ST_ALLOC_CLEAR_REJECTED;
549	              inflight_wg_buffer_gpu_valid_reg <= 1'b0                   ;
550	              wait_tbl_busy                    <= 1'b1                   ;
551	              tbl_walk_rd_en                   <= 1'b0                   ;
552	            end
553	            else begin
554	              tbl_walk_idx                     <= tbl_walk_idx + 1;
555	              tbl_walk_rd_en                   <= 1'b1            ;
556	              inflight_wg_buffer_gpu_valid_reg <= 1'b0            ;
557	              wait_tbl_busy                    <= 1'b1            ;
558	            end
559	          end
560	          else begin
561	            inflight_tbl_alloc_st            <= inflight_tbl_alloc_st;
562	            tbl_walk_idx                     <= tbl_walk_idx         ;
563	            tbl_walk_rd_en                   <= 1'b0                 ;
564	            inflight_wg_buffer_gpu_valid_reg <= 1'b0                 ;
565	            wait_tbl_busy                    <= 1'b1                 ;
566	          end
567	        end
568	
569	        ST_ALLOC_CLEAR_REJECTED : begin//clear the rejected wg
570	          inflight_wg_buffer_gpu_valid_reg  <= 1'b0                 ;
571	          wait_tbl_busy                     <= 1'b1                 ;
572	          tbl_walk_rd_en                    <= 1'b0                 ;
573	          waiting_tbl_pending[tbl_walk_idx] <= 1'b0                 ;
574	          inflight_tbl_alloc_st             <= ST_ALLOC_GET_ALLOC_WG;
575	        end
576	
577	        ST_ALLOC_GET_ALLOC_WG : begin//get the way to be allocated
578	          if(chosen_entry_is_valid) begin
579	            tbl_walk_rd_en                   <= 1'b1                ;
580	            tbl_walk_idx                     <= chosen_entry        ;
581	            chosen_entry_by_allocator        <= chosen_entry        ;
582	            inflight_tbl_alloc_st            <= ST_ALLOC_UP_ALLOC_WG;
583	            inflight_wg_buffer_gpu_valid_reg <= 1'b0;
584	            wait_tbl_busy                    <= 1'b1;
585	          end
586	          else begin
587	            inflight_tbl_alloc_st            <= ST_ALLOC_IDLE;
588	            inflight_wg_buffer_gpu_valid_reg <= 1'b0         ;
589	            wait_tbl_busy                    <= 1'b1         ;
590	            tbl_walk_rd_en                   <= 1'b0         ;
591	          end
592	        end
593	
594	        ST_ALLOC_UP_ALLOC_WG : begin//output to allocator
595	          if(tbl_walk_rd_valid) begin
596	            inflight_wg_buffer_gpu_valid_reg       <= 1'b0                                      ;
597	            wait_tbl_busy                          <= 1'b1                                      ;
598	            tbl_walk_rd_en                         <= 1'b0                                      ;
599	            wg_waiting_alloc_valid                 <= 1'b1                                      ;
600	            inflight_wg_buffer_alloc_wg_id_reg     <= table_walk_rd_reg[WG_ID_H:WG_ID_L]        ;
601	            inflight_wg_buffer_alloc_num_wf_reg    <= table_walk_rd_reg[WG_COUNT_H:WG_COUNT_L]  ;
602	            inflight_wg_buffer_alloc_vgpr_size_reg <= table_walk_rd_reg[VGPR_SIZE_H:VGPR_SIZE_L];
603	            inflight_wg_buffer_alloc_sgpr_size_reg <= table_walk_rd_reg[SGPR_SIZE_H:SGPR_SIZE_L];
604	            inflight_wg_buffer_alloc_lds_size_reg  <= table_walk_rd_reg[LDS_SIZE_H:LDS_SIZE_L]  ;
605	            inflight_wg_buffer_alloc_gds_size_reg  <= table_walk_rd_reg[GDS_SIZE_H:GDS_SIZE_L]  ;
606	            inflight_tbl_alloc_st                  <= ST_ALLOC_IDLE                             ;
607	          end
608	          else begin
609	            inflight_wg_buffer_gpu_valid_reg       <= 1'b0                                  ;
610	            wait_tbl_busy                          <= 1'b1                                  ;
611	            tbl_walk_rd_en                         <= 1'b0                                  ;
612	            wg_waiting_alloc_valid                 <= wg_waiting_alloc_valid                ; 
613	            inflight_wg_buffer_alloc_wg_id_reg     <= inflight_wg_buffer_alloc_wg_id_reg    ; 
614	            inflight_wg_buffer_alloc_num_wf_reg    <= inflight_wg_buffer_alloc_num_wf_reg   ; 
615	            inflight_wg_buffer_alloc_vgpr_size_reg <= inflight_wg_buffer_alloc_vgpr_size_reg; 
616	            inflight_wg_buffer_alloc_sgpr_size_reg <= inflight_wg_buffer_alloc_sgpr_size_reg; 
617	            inflight_wg_buffer_alloc_lds_size_reg  <= inflight_wg_buffer_alloc_lds_size_reg ; 
618	            inflight_wg_buffer_alloc_gds_size_reg  <= inflight_wg_buffer_alloc_gds_size_reg ; 
619	            inflight_tbl_alloc_st                  <= inflight_tbl_alloc_st                 ;
620	          end
621	        end
622	
623	        default : begin
624	          inflight_tbl_alloc_st                       <= ST_ALLOC_IDLE;
625	          waiting_tbl_pending                         <= 'd0          ;
626	          wg_waiting_alloc_valid                      <= 1'b0         ;
627	          wait_tbl_busy                               <= 1'b1         ;
628	          tbl_walk_wg_id_searched                     <= 'd0          ;
629	          tbl_walk_rd_en                              <= 1'b0         ;
630	          tbl_walk_idx                                <= 'd0          ;
631	          inflight_wg_buffer_gpu_valid_reg            <= 'd0          ;
632	          inflight_wg_buffer_gpu_vgpr_size_per_wf_reg <= 'd0          ;
633	          inflight_wg_buffer_gpu_sgpr_size_per_wf_reg <= 'd0          ;
634	          inflight_wg_buffer_gpu_wf_size_reg          <= 'd0          ;
635	          inflight_wg_buffer_start_pc_reg             <= 'd0          ;
636	          inflight_wg_buffer_kernel_size_3d_reg       <= 'd0          ;
637	          inflight_wg_buffer_pds_baseaddr_reg         <= 'd0          ;
638	          inflight_wg_buffer_csr_knl_reg              <= 'd0          ;
639	          inflight_wg_buffer_gds_baseaddr_reg         <= 'd0          ;
640	          chosen_entry_by_allocator                   <= 'd0          ;
641	          inflight_wg_buffer_alloc_wg_id_reg          <= 'd0          ;
642	          inflight_wg_buffer_alloc_num_wf_reg         <= 'd0          ;
643	          inflight_wg_buffer_alloc_vgpr_size_reg      <= 'd0          ;
644	          inflight_wg_buffer_alloc_sgpr_size_reg      <= 'd0          ;
645	          inflight_wg_buffer_alloc_lds_size_reg       <= 'd0          ;
646	          inflight_wg_buffer_alloc_gds_size_reg       <= 'd0          ;
647	        end
648	      endcase
649	    end
650	  end
651	
652	  always@(posedge clk or negedge rst_n) begin
653	    if(!rst_n) begin
654	      waiting_tbl_valid <= 'd0;
655	    end
656	    else if(inflight_tbl_rd_host_st == ST_RD_HOST_ACK_TO_HOST) begin
657	      waiting_tbl_valid[new_index] <= 1'b1;
658	    end
659	    else if(inflight_tbl_alloc_st == ST_ALLOC_CLEAR_ACCEPTED) begin
660	      waiting_tbl_valid[tbl_walk_idx] <= 1'b0;
661	    end
662	    else begin
663	      waiting_tbl_valid <= waiting_tbl_valid;
664	    end
665	  end
666	
667	  //选择ram存储空间来缓存host发送的wg任务
668	  always@(posedge clk or negedge rst_n) begin
669	    if(!rst_n) begin
670	      new_index             <= 'd0;
671	      chosen_entry          <= 'd0;
672	      chosen_entry_is_valid <= 'd0;
673	    end
674	    else begin
675	      new_index             <= new_index_comb            ;
676	      chosen_entry          <= chosen_entry_comb         ;
677	      chosen_entry_is_valid <= chosen_entry_is_valid_comb;
678	    end
679	  end
680	
681	  /*genvar i;
682	  generate for(i=`NUMBER_ENTRIES-1;i>=0;i=i-1) begin : B1
683	    assign found_entry_valid   = (!waiting_tbl_valid[i]) ? 1'b1 : 1'b0                      ;
684	    assign idx_found_entry     = (!waiting_tbl_valid[i]) ? i    : 'd0                       ;
685	    assign found_entry_valid_c = waiting_tbl_valid[i] ? 1'b1 : 1'b0                         ;
686	    assign idx_found_entry_c   = waiting_tbl_valid[i] ? (i + last_chosen_entry_rr + 1) : 'd0;
687	  end
688	  endgenerate*/
689	
690	  //以最低位为最高优先级寻找空闲空间来存储host发送的wg
691	  fixed_pri_arb #(
692	    .ARB_WIDTH(`NUMBER_ENTRIES))
693	  U_fixed_pri_arb (
694	    .req  (~waiting_tbl_valid),
695	    .grant(idx_found_entry_oh)
696	    );
697	
698	  one2bin #(
699	    .ONE_WIDTH(`NUMBER_ENTRIES  ),
700	    .BIN_WIDTH(`ENTRY_ADDR_WIDTH))
701	  U_one2bin (
702	    .oh (idx_found_entry_oh),
703	    .bin(idx_found_entry   )
704	    );
705	  
706	  //assign found_entry_valid          = &waiting_tbl_valid ;
707	
708	  assign new_index_comb             = idx_found_entry    ;
709	  assign chosen_entry_is_valid_comb = found_entry_valid_c;
710	  assign chosen_entry_comb          = idx_found_entry_c  ;
711	
712	  assign left_degree                = `NUMBER_ENTRIES - (1 + last_chosen_entry_rr);
713	  assign right_degree               = 1 + last_chosen_entry_rr                    ;
714	
715	  //选择ram中新地址的wg发送给allocator_neo模块进行能否执行的判断(RR)
716	  genvar j;
717	  generate for(j=0;j<`NUMBER_ENTRIES;j=j+1) begin :B2
718	    assign waiting_tbl_valid_rotated[j] = (j >= left_degree) ? valid_not_pending[j - left_degree] : valid_not_pending[j + right_degree];
719	  end
720	  endgenerate
721	
722	  //以最低位为最高优先级寻找寻找下一个发送给allocator_neo模块的wg
723	  fixed_pri_arb #(
724	    .ARB_WIDTH(`NUMBER_ENTRIES))
725	  U_fixed_pri_arb_1 (
726	    .req  (waiting_tbl_valid_rotated),
727	    .grant(idx_found_entry_c_oh     )
728	    );
729	
730	  one2bin #(
731	    .ONE_WIDTH(`NUMBER_ENTRIES  ),
732	    .BIN_WIDTH(`ENTRY_ADDR_WIDTH))
733	  U_one2bin_1 (
734	    .oh (idx_found_entry_c_oh ),
735	    .bin(idx_found_entry_c_bin)
736	    );
737	
738	  assign idx_found_entry_c          = idx_found_entry_c_bin + last_chosen_entry_rr + 1;
739	  assign found_entry_valid_c        = |waiting_tbl_valid_rotated; 
740	
741	endmodule
742	
743	
744	
