215	    end
216	    else if(inflight_wg_buffer_gpu_valid_i) begin
217	      inflight_wg_buffer_gpu_wf_size_reg          <= inflight_wg_buffer_gpu_wf_size_i         ; 
218	      inflight_wg_buffer_start_pc_reg             <= inflight_wg_buffer_start_pc_i            ;
219	      inflight_wg_buffer_kernel_size_3d_reg       <= inflight_wg_buffer_kernel_size_3d_i      ;
