235	      inflight_wg_buffer_gpu_wf_size_reg          <= inflight_wg_buffer_gpu_wf_size_reg         ;  
236	      inflight_wg_buffer_start_pc_reg             <= inflight_wg_buffer_start_pc_reg            ;
237	      inflight_wg_buffer_kernel_size_3d_reg       <= inflight_wg_buffer_kernel_size_3d_reg      ;
238	      inflight_wg_buffer_pds_baseaddr_reg         <= inflight_wg_buffer_pds_baseaddr_reg        ;
239	      inflight_wg_buffer_csr_knl_reg              <= inflight_wg_buffer_csr_knl_reg             ;
