242	      inflight_wg_buffer_gpu_sgpr_size_per_wf_reg <= inflight_wg_buffer_gpu_sgpr_size_per_wf_reg;
243	      allocator_wg_id_out_reg                     <= allocator_wg_id_out_reg                    ;
244	      allocator_cu_id_out_reg                     <= allocator_cu_id_out_reg                    ;
245	      allocator_wf_count_reg                      <= allocator_wf_count_reg                     ;
246	      allocator_vgpr_start_out_reg                <= allocator_vgpr_start_out_reg               ;
247	      allocator_sgpr_start_out_reg                <= allocator_sgpr_start_out_reg               ;
248	      allocator_lds_start_out_reg                 <= allocator_lds_start_out_reg                ;
249	    end
250	  end
251	
252	  // On allocation
253		// Receives wg_id, waits for sizes per wf
254		// Pass values to cu_handler -> for each dispatch in 1, pass one wf to cus
255		// after passing, sets itself as available again
256	  always@(posedge clk or negedge rst_n) begin
257	    if(!rst_n) begin
258	      gpu_interface_alloc_available_reg       <= 'd0          ;
259	      handler_wg_alloc_en                     <= 'd0          ;
260	      handler_wg_alloc_wg_id                  <= 'd0          ;
261	      handler_wg_alloc_wf_count               <= 'd0          ;
262	      alloc_st                                <= ST_ALLOC_IDLE;
263	      dispatch2cu_wf_dispatch_reg             <= 'd0          ; 
264	      dispatch2cu_wg_wf_count_reg             <= 'd0          ;
265	      dispatch2cu_wf_size_dispatch_reg        <= 'd0          ;
266	      dispatch2cu_sgpr_base_dispatch_reg      <= 'd0          ;
267	      dispatch2cu_vgpr_base_dispatch_reg      <= 'd0          ;
268	      dispatch2cu_wf_tag_dispatch_reg         <= 'd0          ;
269	      dispatch2cu_lds_base_dispatch_reg       <= 'd0          ;
270	      dispatch2cu_start_pc_dispatch_reg       <= 'd0          ;
271	      dispatch2cu_kernel_size_3d_dispatch_reg <= 'd0          ;
272	      dispatch2cu_pds_baseaddr_dispatch_reg   <= 'd0          ;
273	      dispatch2cu_csr_knl_dispatch_reg        <= 'd0          ;
274	      dispatch2cu_gds_base_dispatch_reg       <= 'd0          ;
275	    end
276	    else begin
277	      case(alloc_st) 
278	        ST_ALLOC_IDLE : begin
279	          if(dis_controller_wg_alloc_valid_reg) begin
280	            if(inflight_wg_buffer_gpu_valid_reg) begin
281	              handler_wg_alloc_en[allocator_cu_id_out_reg]                                                            <= 1'b1                   ;
282	              dispatch2cu_wf_dispatch_reg                                                                             <= 'd0                    ;
283	              handler_wg_alloc_wg_id[(allocator_cu_id_out_reg+1)*`WG_ID_WIDTH-1-:`WG_ID_WIDTH]                        <= allocator_wg_id_out_reg;
284	              handler_wg_alloc_wf_count[(allocator_cu_id_out_reg+1)*`WF_COUNT_WIDTH_PER_WG-1-:`WF_COUNT_WIDTH_PER_WG] <= allocator_wf_count_reg ;
285	              gpu_interface_alloc_available_reg                                                                       <= 1'b0                   ;
286	              alloc_st                                                                                                <= ST_ALLOC_WAIT_HANDLER  ;
287	            end
288	            else begin
289	              handler_wg_alloc_en               <= 'd0                 ;
290	              dispatch2cu_wf_dispatch_reg       <= 'd0                 ;
291	              gpu_interface_alloc_available_reg <= 1'b0                ;
292	              alloc_st                          <= ST_ALLOC_WAIT_BUFFER;
293	            end
294	          end
295	          else begin
296	            handler_wg_alloc_en               <= 'd0 ;
297	            dispatch2cu_wf_dispatch_reg       <= 'd0 ;
298	            gpu_interface_alloc_available_reg <= 1'b1;
299	          end
300	        end
301	
302	        ST_ALLOC_WAIT_BUFFER : begin
303	          if(inflight_wg_buffer_gpu_valid_reg) begin
304	            handler_wg_alloc_en[allocator_cu_id_out_reg]                                                            <= 1'b1                   ;
305	            dispatch2cu_wf_dispatch_reg                                                                             <= 'd0                    ;
306	            handler_wg_alloc_wg_id[(allocator_cu_id_out_reg+1)*`WG_ID_WIDTH-1-:`WG_ID_WIDTH]                        <= allocator_wg_id_out_reg;
307	            handler_wg_alloc_wf_count[(allocator_cu_id_out_reg+1)*`WF_COUNT_WIDTH_PER_WG-1-:`WF_COUNT_WIDTH_PER_WG] <= allocator_wf_count_reg ;
308	            gpu_interface_alloc_available_reg                                                                       <= 1'b0                   ;
309	            alloc_st                                                                                                <= ST_ALLOC_WAIT_HANDLER  ;
310	          end
311	          else begin
312	            handler_wg_alloc_en         <= 'd0;
313	            dispatch2cu_wf_dispatch_reg <= 'd0;
314	          end
315	        end
316	
317	        ST_ALLOC_WAIT_HANDLER : begin
318	          if(dispatch2cu_wf_dispatch_handlers[allocator_cu_id_out_reg]) begin
319	            handler_wg_alloc_en                     <= 'd0                                                                                       ;
320	            dispatch2cu_wf_dispatch_reg             <= {{(`NUMBER_CU-1){1'b0}},1'b1} << allocator_cu_id_out_reg                                  ;
321	            dispatch2cu_wg_wf_count_reg             <= allocator_wf_count_reg                                                                    ;
322	            dispatch2cu_wf_size_dispatch_reg        <= inflight_wg_buffer_gpu_wf_size_reg                                                        ;
323	            dispatch2cu_sgpr_base_dispatch_reg      <= allocator_sgpr_start_out_reg                                                              ;
324	            dispatch2cu_vgpr_base_dispatch_reg      <= allocator_vgpr_start_out_reg                                                              ;
325	            dispatch2cu_wf_tag_dispatch_reg         <= dispatch2cu_wf_tag_dispatch_handlers[(allocator_cu_id_out_reg+1)*`TAG_WIDTH-1-:`TAG_WIDTH];
326	            dispatch2cu_lds_base_dispatch_reg       <= allocator_lds_start_out_reg                                                               ;
327	            dispatch2cu_start_pc_dispatch_reg       <= inflight_wg_buffer_start_pc_reg                                                           ;
328	            dispatch2cu_kernel_size_3d_dispatch_reg <= inflight_wg_buffer_kernel_size_3d_reg                                                     ;
329	            dispatch2cu_pds_baseaddr_dispatch_reg   <= inflight_wg_buffer_pds_baseaddr_reg                                                       ;
330	            dispatch2cu_csr_knl_dispatch_reg        <= inflight_wg_buffer_csr_knl_reg                                                            ;
331	            dispatch2cu_gds_base_dispatch_reg       <= inflight_wg_buffer_gds_base_dispatch_reg                                                  ;
332	            alloc_st                                <= ST_ALLOC_PASS_WF                                                                          ;
333	          end
334	          else begin
335	            handler_wg_alloc_en         <= 'd0;
336	            dispatch2cu_wf_dispatch_reg <= 'd0;
337	          end
338	        end
339	
340	        ST_ALLOC_PASS_WF : begin
341	          if(dispatch2cu_wf_dispatch_handlers[allocator_cu_id_out_reg]) begin
342	            handler_wg_alloc_en                <= 'd0                                                                                       ;
343	            dispatch2cu_wf_dispatch_reg        <= {{(`NUMBER_CU-1){1'b0}},1'b1} << allocator_cu_id_out_reg                                  ;
344	            dispatch2cu_wf_tag_dispatch_reg    <= dispatch2cu_wf_tag_dispatch_handlers[(allocator_cu_id_out_reg+1)*`TAG_WIDTH-1-:`TAG_WIDTH];
345	            dispatch2cu_sgpr_base_dispatch_reg <= dispatch2cu_sgpr_base_dispatch_reg + inflight_wg_buffer_gpu_sgpr_size_per_wf_reg          ;
346	            dispatch2cu_vgpr_base_dispatch_reg <= dispatch2cu_vgpr_base_dispatch_reg + inflight_wg_buffer_gpu_vgpr_size_per_wf_reg          ;
347	          end
348	          else if(invalid_due_to_not_ready_handlers[allocator_cu_id_out_reg]) begin
349	            handler_wg_alloc_en         <= 'd0;
350	            dispatch2cu_wf_dispatch_reg <= 'd0;
351	          end
352	          else begin
353	            handler_wg_alloc_en               <= 'd0          ;
354	            dispatch2cu_wf_dispatch_reg       <= 'd0          ;
355	            gpu_interface_alloc_available_reg <= 1'b1         ;
356	            alloc_st                          <= ST_ALLOC_IDLE;
357	          end
358	        end
359	
360	        default : begin
361	          gpu_interface_alloc_available_reg       <= 'd0          ;
362	          handler_wg_alloc_en                     <= 'd0          ;
363	          handler_wg_alloc_wg_id                  <= 'd0          ;
364	          handler_wg_alloc_wf_count               <= 'd0          ;
365	          alloc_st                                <= ST_ALLOC_IDLE;
366	          dispatch2cu_wf_dispatch_reg             <= 'd0          ;
367	          dispatch2cu_wg_wf_count_reg             <= 'd0          ;
368	          dispatch2cu_wf_size_dispatch_reg        <= 'd0          ;
369	          dispatch2cu_sgpr_base_dispatch_reg      <= 'd0          ;
370	          dispatch2cu_vgpr_base_dispatch_reg      <= 'd0          ;
371	          dispatch2cu_wf_tag_dispatch_reg         <= 'd0          ;
372	          dispatch2cu_lds_base_dispatch_reg       <= 'd0          ;
373	          dispatch2cu_start_pc_dispatch_reg       <= 'd0          ;
374	          dispatch2cu_kernel_size_3d_dispatch_reg <= 'd0          ;
375	          dispatch2cu_pds_baseaddr_dispatch_reg   <= 'd0          ;
376	          dispatch2cu_csr_knl_dispatch_reg        <= 'd0          ;
377	          dispatch2cu_gds_base_dispatch_reg       <= 'd0          ;
378	        end
379	      endcase
380	    end
381	  end
382	
383	  // On dealloc
384		// Ack to the handler
385		// pass info to the dispatcher
386	  always@(posedge clk or negedge rst_n) begin
387	    if(!rst_n) begin
388	      gpu_interface_dealloc_available_reg <= 'd0            ;
389	      gpu_interface_cu_id_reg             <= 'd0            ;
390	      handler_wg_done_ack                 <= 'd0            ;
391	      gpu_interface_dealloc_wg_id_reg     <= 'd0            ;
392	      dealloc_st                          <= ST_DEALLOC_IDLE;
393	    end
394	    else begin
395	      case(dealloc_st) 
396	        ST_DEALLOC_IDLE : begin
397	          if(chosen_done_cu_valid) begin
398	            gpu_interface_dealloc_available_reg    <= 1'b1                                                                     ;
399	            gpu_interface_cu_id_reg                <= chosen_done_cu_id                                                        ;
400	            handler_wg_done_ack[chosen_done_cu_id] <= 1'b1                                                                     ;
401	            gpu_interface_dealloc_wg_id_reg        <= handler_wg_done_wg_id[(chosen_done_cu_id+1)*`WG_ID_WIDTH-1-:`WG_ID_WIDTH];
402	            dealloc_st                             <= ST_DEALLOC_WAIT_ACK                                                      ;
403	          end
404	          else begin
405	            gpu_interface_dealloc_available_reg <= 'd0;
406	            handler_wg_done_ack                 <= 'd0;
407	          end
408	        end
409	
410	        ST_DEALLOC_WAIT_ACK : begin
411	          if(dis_controller_wg_dealloc_valid_reg) begin
412	            gpu_interface_dealloc_available_reg <= 'd0            ;
413	            handler_wg_done_ack                 <= 'd0            ;
414	            dealloc_st                          <= ST_DEALLOC_IDLE;
415	          end
416	          else begin
417	            gpu_interface_dealloc_available_reg <= 1'b1;
418	            handler_wg_done_ack                 <= 'd0 ;
419	          end
420	        end
421	
422	        default : begin
423	          gpu_interface_dealloc_available_reg <= 'd0            ;
424	          gpu_interface_cu_id_reg             <= 'd0            ;
425	          handler_wg_done_ack                 <= 'd0            ;
426	          gpu_interface_dealloc_wg_id_reg     <= 'd0            ;
427	          dealloc_st                          <= ST_DEALLOC_IDLE;
428	        end
429	      endcase
430	    end
431	  end
432	
433	  assign cu_found_valid = |handler_wg_done_valid;
434	  fixed_pri_arb #(
435	    .ARB_WIDTH(`NUMBER_CU)
436	  )
437	  U_fixed_pri_arb (
438	    .req  (handler_wg_done_valid),
439	    .grant(grant                )
440	    );
441	
442	  one2bin #(
443	    .ONE_WIDTH(`NUMBER_CU  ),
444	    .BIN_WIDTH(`CU_ID_WIDTH)
445	  )
446	  U_one2bin (
447	    .oh (grant   ),
448	    .bin(cu_found)
449	    );
450	
451	  assign chosen_done_cu_valid_comb = cu_found_valid;
452	  assign chosen_done_cu_id_comb    = cu_found      ;
453	
454	  assign gpu_interface_dealloc_available_o     = gpu_interface_dealloc_available_reg    ;
455	  assign gpu_interface_dealloc_wg_id_o         = gpu_interface_dealloc_wg_id_reg        ;
456	  assign gpu_interface_cu_id_o                 = gpu_interface_cu_id_reg                ;
457	  assign gpu_interface_alloc_available_o       = gpu_interface_alloc_available_reg      ;
458	  assign dispatch2cu_wf_dispatch_o             = dispatch2cu_wf_dispatch_reg            ;
459	  assign dispatch2cu_wf_tag_dispatch_o         = dispatch2cu_wf_tag_dispatch_reg        ;
460	  assign dispatch2cu_wg_wf_count_o             = dispatch2cu_wg_wf_count_reg            ;
461	  assign dispatch2cu_wf_size_dispatch_o        = dispatch2cu_wf_size_dispatch_reg       ;
462	  assign dispatch2cu_sgpr_base_dispatch_o      = dispatch2cu_sgpr_base_dispatch_reg     ;
463	  assign dispatch2cu_vgpr_base_dispatch_o      = dispatch2cu_vgpr_base_dispatch_reg     ;
464	  assign dispatch2cu_lds_base_dispatch_o       = dispatch2cu_lds_base_dispatch_reg      ;
465	  assign dispatch2cu_start_pc_dispatch_o       = dispatch2cu_start_pc_dispatch_reg      ;
466	  assign dispatch2cu_kernel_size_3d_dispatch_o = dispatch2cu_kernel_size_3d_dispatch_reg;
467	  assign dispatch2cu_pds_baseaddr_dispatch_o   = dispatch2cu_pds_baseaddr_dispatch_reg  ;
468	  assign dispatch2cu_csr_knl_dispatch_o        = dispatch2cu_csr_knl_dispatch_reg       ;
469	  assign dispatch2cu_gds_base_dispatch_o       = dispatch2cu_gds_base_dispatch_reg      ;
470	
471	endmodule
